class Driver final:public IDisplayDriver{public:bool initialized{},cleared{};std::uint8_t frame_brightness{};std::vector<Pixel> last;std::string_view id()const noexcept override{return"test";}DriverCapabilities capabilities()const noexcept override{return{1024,1,true,true,true};}bool initialize(const DisplayConfiguration&)override{initialized=true;return true;}bool set_brightness(std::uint8_t)override{return true;}bool render(FrameView f)override{frame_brightness=f.brightness;last.assign(f.pixels.begin(),f.pixels.end());return true;}void clear()noexcept override{cleared=true;}bool test()override{return true;}};
class Store final:public IConfigurationStore{public:DisplayConfiguration config;std::string active,active_playlist;std::map<std::string,std::vector<Pixel>> scenes;std::map<std::string,std::vector<std::uint8_t>> blobs;std::vector<Playlist>playlists;std::vector<Schedule>schedules;std::optional<NetworkCredentials>credentials;std::optional<DisplayConfiguration>load_display()override{return config.width?std::optional<DisplayConfiguration>{config}:std::nullopt;}bool save_display(const DisplayConfiguration&c)override{config=c;return true;}std::optional<std::string>load_active_scene_id()override{return active.empty()?std::nullopt:std::optional<std::string>{active};}bool save_active_scene_id(std::string_view id)override{active=id;return true;}std::optional<std::vector<Pixel>>load_scene_frame(std::string_view id)override{auto i=scenes.find(std::string{id});return i==scenes.end()?std::nullopt:std::optional<std::vector<Pixel>>{i->second};}bool save_scene_frame(std::string_view id,const std::vector<Pixel>&p)override{scenes[std::string{id}]=p;return true;}std::optional<NetworkCredentials>load_network()override{return credentials;}bool save_network(const NetworkCredentials&value)override{credentials=value;return true;}bool clear_network()override{credentials.reset();return true;}bool save_scene_blob(std::string_view id,const std::vector<std::uint8_t>&value)override{blobs[std::string{id}]=value;return true;}std::optional<std::vector<std::uint8_t>>load_scene_blob(std::string_view id)override{auto i=blobs.find(std::string{id});return i==blobs.end()?std::nullopt:std::optional<std::vector<std::uint8_t>>{i->second};}std::vector<Playlist>load_playlists()override{return playlists;}bool save_playlist(const Playlist&p)override{auto i=std::find_if(playlists.begin(),playlists.end(),[&p](const auto&v){return v.id==p.id;});if(i==playlists.end())playlists.push_back(p);else*i=p;return true;}std::vector<Schedule>load_schedules()override{return schedules;}bool save_schedule(const Schedule&s)override{auto i=std::find_if(schedules.begin(),schedules.end(),[&s](const auto&v){return v.id==s.id;});if(i==schedules.end())schedules.push_back(s);else*i=s;return true;}std::optional<std::string>load_active_playlist_id()override{return active_playlist.empty()?std::nullopt:std::optional<std::string>{active_playlist};}bool save_active_playlist_id(std::string_view id)override{active_playlist=id;return true;}};
