    MatrixMapper mapper{config()};assert(mapper.map(0,0).absolute_index==0);assert(mapper.map(3,1).absolute_index==4);
    std::vector<Pixel> pixels(8);pixels[3+4]={10,20,30,0};auto bytes=mapper.encode({4,2,ColorModel::rgb,255,pixels});assert(bytes[12]==20&&bytes[13]==10&&bytes[14]==30);
