    Store secure_store;CredentialVault vault;Network secure_network;ProvisioningManager secure_provisioning{secure_store,secure_network,log,&vault};assert(secure_provisioning.boot());assert(secure_provisioning.submit({"SecureLAN","password123"}).accepted&&vault.value.has_value()&&!secure_store.credentials.has_value());
    LocalApi api{runtime,store,provisioning,config()};assert(api.handle({HttpMethod::get,"/api/status",{}, {}}).status==200);assert(api.handle({HttpMethod::post,"/api/brightness",{'{','\"','b','r','i','g','h','t','n','e','s','s','\"',':','1','2','8','}'},{}}).status==200);
    std::vector<std::uint8_t> frame(14+24);frame[0]='A';frame[1]='T';frame[2]='L';frame[3]='F';frame[4]=1;frame[5]=4;frame[7]=2;frame[10]=24;frame[14]=255;
    assert(api.handle({HttpMethod::post,"/api/frame",frame,{}}).status==200);frame[10]=23;assert(api.handle({HttpMethod::post,"/api/frame",frame,{}}).status==400);
    const std::vector<std::uint8_t> scene{'{','}'};assert(api.handle({HttpMethod::post,"/api/scene",scene,"scene-json"}).status==200&&store.blobs.count("scene-json")==1);
    assert(api.handle({HttpMethod::post,"/api/scene",{},"bad"}).status==413);assert(api.handle({HttpMethod::get,"/missing",{}, {}}).status==404);
