    AddressableDriver sk6812{addressable_transport,sk6812_rgbw_profile};auto rgbw_config=config();rgbw_config.color_model=ColorModel::rgbw;assert(sk6812.initialize(rgbw_config));driver_pixels[0]={1,2,3,4};assert(sk6812.render({4,2,ColorModel::rgbw,255,driver_pixels}));assert(addressable_transport.bytes.size()==32&&addressable_transport.bytes[0]==2&&addressable_transport.bytes[3]==4);
    ClockedTransport clocked_transport;ClockedDriver apa102{clocked_transport,apa102_profile};assert(apa102.initialize(rgb_config));assert(apa102.render({4,2,ColorModel::rgb,255,driver_pixels}));assert(clocked_transport.frequency==8000000&&clocked_transport.bytes.size()==37&&clocked_transport.bytes[4]==0xFF&&clocked_transport.bytes[5]==3&&clocked_transport.bytes[6]==2&&clocked_transport.bytes[7]==1);
    Hub75Transport hub75_transport;Hub75Driver hub75{hub75_transport};assert(hub75.initialize(rgb_config));assert(hub75.render({4,2,ColorModel::rgb,128,driver_pixels}));assert(hub75_transport.width==4&&hub75_transport.height==2&&hub75_transport.pixels[0]==driver_pixels[0]&&hub75_transport.brightness==128);
    std::vector<Pixel> white(8,Pixel{255,255,255,0});PowerManager power{{5000,200,50,255,20}};const auto decision=power.evaluate({4,2,ColorModel::rgb,255,white},255);assert(decision.limited&&decision.budget_milliamps==150&&decision.estimated_milliamps<=150&&decision.estimated_milliwatts<=750);
    PowerManager no_pixel_budget{{5000,100,200,255,20}};assert(no_pixel_budget.evaluate({4,2,ColorModel::rgb,255,white},255).applied_brightness==0);std::vector<Pixel> rgbw_white(1,Pixel{255,255,255,255});PowerManager rgbw_power{{5000,1000,0,128,20}};const auto rgbw_decision=rgbw_power.evaluate({1,1,ColorModel::rgbw,255,rgbw_white},255);assert(!rgbw_decision.limited&&rgbw_decision.requested_brightness==128&&rgbw_decision.estimated_milliamps==40);
