    assert(scheduler.save({"business-hours","daily",1u<<1,60,120,5,true}));assert(scheduler.save({"overnight","daily",1u<<1,1380,60,9,true}));scheduler_clock.day=1;scheduler_clock.minute=90;PlaylistScheduler scheduled_restart{schedule_runtime,schedule_store,scheduler_clock};assert(scheduled_restart.boot()&&scheduled_restart.active_schedule_id()=="business-hours");scheduler_clock.day=2;scheduler_clock.minute=30;assert(scheduled_restart.tick()&&scheduled_restart.active_schedule_id()=="overnight"&&schedule_runtime.status().active_playlist_id=="daily");
    scheduler_clock.synced=false;scheduler_clock.now+=1000;assert(scheduled_restart.tick()&&scheduled_restart.active_schedule_id()=="overnight");
